import { useRef } from "react";
import {
  AudioVisualizerRoot,
  useAudioVisualizer,
} from "@/components/bevelui/audio-visualizer";

function PlayButton() {
  const { connect, start, resume } = useAudioVisualizer();
  const audioRef = useRef<HTMLAudioElement>(null);

  async function onPlay() {
    await resume(); // required by browser autoplay policy
    if (audioRef.current) {
      connect(audioRef.current);
      audioRef.current.play();
      start();
    }
  }

  return (
    <>
      <audio ref={audioRef} src="/track.mp3" crossOrigin="anonymous" />
      <button onClick={onPlay}>Play</button>
    </>
  );
}

export default function PlayerPage() {
  return (
    <AudioVisualizerRoot
      className="h-40 w-full"
      config={{ mode: "bars", barCount: 64, color: "#c2f13c" }}
    >
      <PlayButton />
    </AudioVisualizerRoot>
  );
}

const { connect, start, resume } = useAudioVisualizer();

async function onPlay(el: HTMLAudioElement) {
  await resume();
  connect(el);
  el.play();
  start();
}

const { connect, start, resume } = useAudioVisualizer();

async function onEnableMic() {
  await resume();
  const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
  connect(stream);
  start();
}

const { connect, start, resume } = useAudioVisualizer();

async function onPlayBuffer(buffer: AudioBuffer) {
  await resume();
  connect(buffer); // starts playback of the buffer immediately
  start();
}

import {
  AudioVisualizerRoot,
  VisualizerCanvas,
  useAudioVisualizer,
} from "@/components/bevelui/audio-visualizer";

function Toolbar() {
  const { isRunning, mode, setMode } = useAudioVisualizer();
  return (
    <div className="flex items-center justify-between">
      <span>{isRunning ? "Rendering" : "Idle"}</span>
      <button onClick={() => setMode(mode === "bars" ? "wave" : "bars")}>
        Toggle mode
      </button>
    </div>
  );
}

export function Player() {
  return (
    <AudioVisualizerRoot config={{ mode: "bars" }}>
      <Toolbar />
      <div className="h-32 rounded-lg border border-border">
        <VisualizerCanvas />
      </div>
    </AudioVisualizerRoot>
  );
}

